SELECT jsonb_build_object('events',(SELECT jsonb_agg(to_jsonb(x) ORDER BY data_inicial,id_evento) FROM (SELECT e.id_evento,e.nome_evento,e.tag,e.data_inicial,e.data_final,e.cidade,e.estado,e.ativo,e.url_hotsite,e.url_inscricao,e.id_agrega_evento,md5(to_jsonb(e)::text) AS row_hash,(SELECT coalesce(jsonb_agg(to_jsonb(ge)),'[]') FROM tb_agregadores_eventos ge WHERE ge.id_evento=e.id_evento) AS memberships FROM tb_evento_corridas e WHERE e.ativo AND e.data_final>=current_date AND ((unaccent(e.nome_evento) ILIKE '%estacoes%' OR e.url_hotsite ILIKE '%circuito%estacoes%' OR e.url_inscricao ILIKE '%circuito%estacoes%') AND (e.cidade ILIKE '%Florian%' OR e.cidade ILIKE '%Ribeir%')) ) x))::text payload
